import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        long total = 0;
        for (int i = 0; i < n; i++) {
            total += Long.parseLong(sc.next());
        }
        System.out.println(total);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        long total = 0;
        for (int i = 0; i < n; i++) {
            long amount = Long.parseLong(sc.next());
            if (amount >= 2000) {
                total += amount;
            }
        }
        System.out.println(total);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int correct = Integer.parseInt(sc.next());
        int attempts = 0;
        int attempt;
        do {
            attempt = Integer.parseInt(sc.next());
            attempts++;
        } while (attempt != correct);
        System.out.println(attempts);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        int max = 0;
        for (int i = 0; i < n; i++) {
            int expense = Integer.parseInt(sc.next());
            if (expense > max) {
                max = expense;
            }
        }
        System.out.println(max);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        long result = 1;
        for (int i = 1; i <= n; i++) {
            result *= i;
        }
        System.out.println(result);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        int k = Integer.parseInt(sc.next());
        for (int value = n; value >= 1; value -= k) {
            System.out.println(value);
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        int k = Integer.parseInt(sc.next());
        for (int i = 1; i <= k; i++) {
            System.out.println(n + " x " + i + " = " + (n * i));
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        int failedAt = 0;
        for (int i = 0; i < n; i++) {
            int score = Integer.parseInt(sc.next());
            if (score < 60) {
                failedAt = i + 1;
                break;
            }
        }
        if (failedAt == 0) {
            System.out.println("All Passed");
        } else {
            System.out.println(failedAt);
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long target = Long.parseLong(sc.next());
        int n = Integer.parseInt(sc.next());
        long total = 0;
        int days = 0;
        for (int i = 0; i < n; i++) {
            total += Long.parseLong(sc.next());
            days++;
            if (total >= target) {
                break;
            }
        }
        System.out.println(days);
        System.out.println(total);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        long total = 0;
        for (int i = 0; i < n; i++) {
            int hours = Integer.parseInt(sc.next());
            if (hours <= 8) {
                total += hours * 200;
            } else {
                total += 8 * 200 + (hours - 8) * 300;
            }
        }
        System.out.println(total);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        int previous = Integer.parseInt(sc.next());
        int pairs = 0;
        for (int i = 1; i < n; i++) {
            int current = Integer.parseInt(sc.next());
            if (previous > 50000 && current > 50000) {
                pairs++;
            }
            previous = current;
        }
        System.out.println(pairs);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long code = Long.parseLong(sc.next());
        int sum = 0;
        while (code > 0) {
            sum += code % 10;
            code /= 10;
        }
        System.out.println(sum);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = Long.parseLong(sc.next());
        long b = Long.parseLong(sc.next());
        while (b != 0) {
            long remainder = a % b;
            a = b;
            b = remainder;
        }
        System.out.println(a);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int start = Integer.parseInt(sc.next());
        int end = Integer.parseInt(sc.next());
        int d1 = Integer.parseInt(sc.next());
        int d2 = Integer.parseInt(sc.next());
        int found = -1;
        for (int number = start; number <= end; number++) {
            if (number % d1 == 0 && number % d2 == 0) {
                found = number;
                break;
            }
        }
        if (found == -1) {
            System.out.println("Not Found");
        } else {
            System.out.println(found);
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        int k = Integer.parseInt(sc.next());
        boolean printedAny = false;
        for (int i = 1; i <= n; i++) {
            if (i % k == 0) {
                continue;
            }
            System.out.println(i);
            printedAny = true;
        }
        if (!printedAny) {
            System.out.println("No Values");
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        int current = 0;
        int longest = 0;
        for (int i = 0; i < n; i++) {
            int value = Integer.parseInt(sc.next());
            if (value == 1) {
                current++;
                if (current > longest) {
                    longest = current;
                }
            } else {
                current = 0;
            }
        }
        System.out.println(longest);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int r = Integer.parseInt(sc.next());
        int c = Integer.parseInt(sc.next());
        for (int row = 1; row <= r; row++) {
            for (int col = 1; col <= c; col++) {
                if (col > 1) {
                    System.out.print(" ");
                }
                System.out.print("*");
            }
            System.out.println();
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long target = Long.parseLong(sc.next());
        int n = Integer.parseInt(sc.next());
        long total = 0;
        int days = 0;
        boolean reached = false;
        for (int i = 0; i < n; i++) {
            total += Long.parseLong(sc.next());
            days++;
            if (total >= target) {
                reached = true;
                break;
            }
        }
        if (reached) {
            System.out.println("Target Reached");
            System.out.println(days);
            System.out.println(total);
        } else {
            System.out.println("Target Not Reached");
            System.out.println(total);
        }
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int l = Integer.parseInt(sc.next());
        int r = Integer.parseInt(sc.next());
        int count = 0;
        for (int number = l; number <= r; number++) {
            boolean isPrime = true;
            for (int d = 2; d * d <= number; d++) {
                if (number % d == 0) {
                    isPrime = false;
                    break;
                }
            }
            if (isPrime) {
                count++;
            }
        }
        System.out.println(count);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = Integer.parseInt(sc.next());
        int successes = 0;
        int failures = 0;
        int current = 0;
        int currentStart = 0;
        int best = 0;
        int bestStart = 0;
        for (int i = 1; i <= n; i++) {
            int outcome = Integer.parseInt(sc.next());
            if (outcome == 1) {
                successes++;
                current = 0;
            } else {
                failures++;
                if (current == 0) {
                    currentStart = i;
                }
                current++;
                if (current > best) {
                    best = current;
                    bestStart = currentStart;
                }
            }
        }
        System.out.println(successes);
        System.out.println(failures);
        System.out.println(best);
        System.out.println(bestStart);
    }
}
